def classifier_free_guidance(uncond_prediction, cond_prediction, guidance_scale):
    return uncond_prediction + guidance_scale * (cond_prediction - uncond_prediction)

uncond = torch.tensor([0.2, 0.4])
cond = torch.tensor([0.5, 0.7])
guided = classifier_free_guidance(uncond, cond, guidance_scale=2.0)
print(guided)
